var front_default$1 = "<!-- section front: Strona tytułowa, dedykacja, spis treści (scan p001–p007) | scan p001–p007 | missing: none -->\n\n<!-- scan p001 | printed page – | type: front -->\n\n[front cover: dark green cloth binding, no printed text]\n[label, lower spine edge, printed: R.002755]\n\n\n<!-- scan p002 | printed page – | type: front -->\n\n[inside front cover / pastedown]\n[handwritten, top left: + 3 opinie]\n[stamp: ex libris bookplate — POLITECHNIKI WARSZAWSKIEJ / EX LIBRIS / BIBLIOTEKI GŁÓWNEJ]\n[handwritten on bookplate: R. 2755]\n\n\n<!-- scan p003 | printed page – | type: front -->\n\n[handwritten, top: [681.2.08 : 536.4 : 537.311.33] : 043]\n\nPOLITECHNIKA WARSZAWSKA\n\nWYDZIAŁ MECHANIKI PRECYZYJNEJ\nINSTYTUT METROLOGII I BUDOWY PRZYRZĄDÓW POMIAROWYCH\n\nmgr inż. Janusz BRYZEK\n\nMETODA KOMPENSACJI WPŁYWU TEMPERATURY\nW PÓŁPRZEWODNIKOWYCH PRZETWORNIKACH CISNIENIA\n\nPraca doktorska\n\nPROMOTOR PRACY\ndoc. dr inż. Wojciech WŁODARSKI\n\nWARSZAWA\n\n1978\n\n<!-- scan p004 | printed page – | type: front -->\n\n[verso of title page; bleed-through of the title page not transcribed]\n[stamp, oval, red: POLITECHNIKA WARSZAWSKA / Biblioteka Główna]\n[handwritten inside the stamp, blue ink: R. 2755]\n[handwritten, bottom, pencil: 167-2-78/d]\n\n\n<!-- scan p005 | printed page – | type: front -->\n\nSPIS TRESCI\n\n|  |  | str. |\n|---|---|---|\n| 1. | Wstęp | 5 |\n| 1. 1. | Wprowadzenie | 5 |\n| 1. 2. | Cel i teza pracy | 6 |\n| 2. | Istota błędów temperaturowych | 9 |\n| 3. | Przegląd metod kompensacji wpływu temperatury z zastosowaniem obwodów kompensacji w analogowej części układu przetwarzającego | 18 |\n| 3. 1. | Wstęp | 18 |\n| 3. 2. | Metoda z zastosowaniem czujnika ciśnienia jako czujnika temperatury | 18 |\n| 3. 3. | Metody z zastosowaniem dyskretnych elementów o zmiennej rezystancji próbkujących temperaturę | 20 |\n| 3. 4. | Metody z zastosowaniem dyskretnych złączowych przyrządów półprzewodnikowych jako czujników temperatury | 26 |\n| 3. 5. | Metody z zastosowaniem scalonych elementów rezystancyjnych jako czujników temperatury | 30 |\n| 3. 6. | Metoda z zastosowaniem scalonych przyrządów półprzewodnikowych jako czujników temperatury | 34 |\n| 3. 7. | Podsumowanie | 38 |\n| 4. | Nowa metoda kompensacji błędów temperaturowych | 38 |\n| 4. 1. | Wprowadzenie | 38 |\n| 4. 2. | Warunki wystarczające kompensacji temperaturowej charakterystyki przetwarzania przetwornika | 39 |\n| 4. 3. | Istota pełnej kompensacji temperaturowej | 43 |\n| 4. 3. 1. | Synteza metody | 43 |\n| 4. 3. 2. | Procedura kompensacji | 48 |\n| 4. 3. 3. | Warunki wystarczające kompensacji temperaturowej pełnej | 52 |\n| 4. 4. | Istota niepełnej kompensacji temperaturowej | 58 |\n| 4. 4. 1. | Przypadek s = 2, m = 1, n = 1 | 58 |\n| 4. 4. 2. | Przypadek s = 3, m = 1, n = 1 | 62 |\n| 4. 4. 3. | Przypadek s = 3, m = 1, n = 2 | 65 |\n\n\n<!-- scan p006 | printed page – | type: front -->\n\n|  |  | str. |\n|---|---|---|\n| 4. 5. | Podsumowanie | 69 |\n| 5. | Realizacja praktyczna metody | 72 |\n| 5. 1. | Mostek trójkrotny | 74 |\n| 5. 2. | Zagadnienie wzajemnego uzależnienia kompensacji wartości początkowej i końcowej | 76 |\n| 6. | Zastosowanie nowej metody kompensacji w piezorezystancyjnym przetworniku ciśnienia | 79 |\n| 6. 1. | Wstęp | 79 |\n| 6. 2. | Wymagane parametry metrologiczne przetwornika | 79 |\n| 6. 3. | Czujnik | 80 |\n| 6. 3. 1. | Budowa | 81 |\n| 6. 3. 2. | Zródła błędów temperaturowych | 82 |\n| 6. 3. 3. | Dobór parametrów układu kompensacji temperaturowej | 83 |\n| 6. 4. | Układ elektroniczny przetwornika | 88 |\n| 6. 4. 1. | Układ blokowy | 88 |\n| 6. 4. 2. | Wybór czujników próbkujących temperaturę | 90 |\n| 6. 4. 3. | Optymalizacja charakterystyk mostka kompensującego dryft zera | 92 |\n| 6. 4. 4. | Optymalizacja charakterystyk mostka kompensującego dryft zakresu | 96 |\n| 6. 5. | Procedura kompensacji | 100 |\n| 6. 6. | Badania przetworników | 102 |\n| 6. 6. 1. | Układ pomiarowy | 102 |\n| 6. 6. 2. | Analiza błędów | 103 |\n| 6. 6. 3. | Wyniki badań | 104 |\n| 7. | Wnioski | 108 |\n| 8. | Bibliografia | 111 |\n| 9. | Dodatek | 120 |\n| 9. 1. | Opis programu optymalizującego charakterystyki mostka kompensującego dryft zera | 120 |\n| 9. 2. | Opis programu optymalizującego charakterystyki mostka kompensującego dryft zakresu | 122 |\n\n\n<!-- scan p007 | printed page – | type: front -->\n\n[dedication page; bleed-through of printed page 5 (1. Wstęp) not transcribed]\n\nPracę tę żonie mojej, Barbarze, poświęcam\n\n";
